schemas.schema-01-systematic.prisma:
/// Represents a communication channel for the discussion board. Channels can
/// be used for different topics or categories of discussions.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model channels {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Name of the channel.
  name String

  /// Description of the channel.
  description String?
}

/// Stores configuration settings for the discussion board. This can include
/// site-wide settings, feature flags, and other configurable options.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model configurations {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Configuration key.
  key String

  /// Configuration value.
  value String

  //----
  // RELATIONS
  //----
  @@unique([key])
}

schemas.schema-02-actors.prisma:
/// User information, but not a person but a connection basis
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model users {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Email for notifications and login.
  email String

  /// Password hash for secure authentication.
  password_hash String

  //----
  // RELATIONS
  //----
  user_sessions user_sessions[]
  comments comments[]
  replies replies[]
  access_tokens access_tokens[]
  refresh_tokens refresh_tokens[]
  notifications notifications[]

  @@unique([email])
}

/// User session information for authentication
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model user_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Foreign Key. {@link users.id}
  user_id String @db.Uuid

  /// IP address of the user's device.
  ip String

  /// URL of the user's session.
  href String

  /// Referrer URL of the user's session.
  referrer String

  /// Timestamp when the session was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the session expires.
  expired_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user users @relation(fields: [user_id], references: [id], onDelete: Cascade)

  @@index([user_id, created_at])
}

