schemas.schema-03-articles.prisma:
/// Main entity for articles on the discussion board. Each article can have
/// multiple attachments.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model articles {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belongs to member. {@link members.id}
  member_id String @db.Uuid

  /// Article title.
  title String

  /// Article content.
  content String

  /// Timestamp when the article was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the article was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the article was soft-deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  member members @relation(fields: [member_id], references: [id], onDelete: Cascade)

  article_attachments article_attachments[]
  comments comments[]
  attachments attachments[]

  @@index([member_id])
}

/// Junction table for article attachments. Establishes many-to-many
/// relationships between articles and attachments.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model article_attachments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belongs to article. {@link articles.id}
  article_id String @db.Uuid

  /// Belongs to attachment. {@link attachments.id}
  attachment_id String @db.Uuid

  //----
  // RELATIONS
  //----
  article articles @relation(fields: [article_id], references: [id], onDelete: Cascade)
  attachment attachments @relation(fields: [attachment_id], references: [id], onDelete: Cascade)

  @@index([article_id])
  @@index([attachment_id])
}

schemas.schema-04-comments.prisma:
/// Main entity for threaded comments on articles.
///
/// @namespace Comments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model comments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// FK to articles.id.
  article_id String @db.Uuid

  /// FK to users.id.
  user_id String @db.Uuid

  /// Comment text content.
  content String

  /// Comment creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Comment last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp (nullable).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  article articles @relation(fields: [article_id], references: [id], onDelete: Cascade)
  user users @relation(fields: [user_id], references: [id], onDelete: Cascade)

  replies replies[]
  attachments attachments[]

  @@index([article_id])
  @@index([user_id])
}

/// Subentity for threaded replies to comments.
///
/// @namespace Comments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model replies {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// FK to comments.id.
  comment_id String @db.Uuid

  /// FK to users.id.
  user_id String @db.Uuid

  /// Reply text content.
  content String

  /// Reply creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Reply last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp (nullable).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  comment comments @relation(fields: [comment_id], references: [id], onDelete: Cascade)
  user users @relation(fields: [user_id], references: [id], onDelete: Cascade)

  @@index([comment_id])
  @@index([user_id])
}

schemas.schema-05-attachments.prisma:
/// Stores information about file attachments for articles and comments.
///
/// @namespace Attachments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model attachments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Foreign key referencing the articles table.
  article_id String @db.Uuid

  /// Foreign key referencing the comments table.
  comment_id String? @db.Uuid

  /// Name of the attached file.
  file_name String

  /// Type of the attached file (e.g., image/jpeg, application/pdf).
  file_type String

  /// Size of the attached file in bytes.
  file_size Int @db.Integer

  /// Timestamp when the file was uploaded.
  uploaded_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  article articles @relation(fields: [article_id], references: [id], onDelete: Cascade)
  comment comments? @relation(fields: [comment_id], references: [id], onDelete: Cascade)

  article_attachments article_attachments[]

  @@index([comment_id])

  @@index([article_id, file_name])
}

