schemas.main.prisma:
generator client {
  provider        = "prisma-client-js"
  engineType      = "client"
  previewFeatures = ["postgresqlExtensions", "views"]
}
datasource db {
  provider   = "postgresql"
  url        = env("DATABASE_URL")
  extensions = [pg_trgm]
}
generator markdown {
  provider = "prisma-markdown"
  output   = "../../docs/ERD.md"
}
